import React, { useState, useRef, useEffect } from "react";
import {
  HashRouter as Router,
  Routes,
  Route,
  Link,
  useLocation,
} from "react-router-dom";
import Home from "./components/Home";
import Financials from "./components/Financials";
import ItemsTable from "./components/ItemsTable";
import AddItem from "./components/AddItem";
import Expenses from "./components/Expenses";
import Other from "./components/Other";
import Binder from "./components/Binder";
import ExportTransactions from "./components/ExportTransactions";
import MarketValueCalculator from "./components/MarketValueCalculator";
import Insights from "./components/Insights";
import Shows from "./components/Shows";
import ShowPnL from "./components/ShowPnL";
import "./App.css";

const NavLink = ({ to, children }) => {
  const location = useLocation();
  const isActive = location.pathname === to;
  return (
    <Link to={to} className={`nav-link ${isActive ? "nav-link--active" : ""}`}>
      {children}
    </Link>
  );
};

const NavDropdown = ({ label, links }) => {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);
  const location = useLocation();
  const isActive = links.some((l) => location.pathname === l.to);

  useEffect(() => {
    const handler = (e) => {
      if (ref.current && !ref.current.contains(e.target)) setOpen(false);
    };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, []);

  return (
    <div ref={ref} style={{ position: "relative" }}>
      <button
        className={`nav-link nav-link--btn ${isActive ? "nav-link--active" : ""}`}
        onClick={() => setOpen((p) => !p)}
      >
        {label}{" "}
        <span style={{ fontSize: 10, marginLeft: 2 }}>{open ? "▲" : "▼"}</span>
      </button>
      {open && (
        <div className="nav-dropdown">
          {links.map((l) => (
            <Link
              key={l.to}
              to={l.to}
              className="nav-dropdown__item"
              onClick={() => setOpen(false)}
            >
              {l.label}
            </Link>
          ))}
        </div>
      )}
    </div>
  );
};

function App() {
  return (
    <Router>
      <div className="app">
        <nav className="navbar">
          <div className="navbar__brand">
            <img
              src={process.env.PUBLIC_URL + "/logo.png"}
              alt="Statis Cards Logo"
              className="navbar__logo-img"
            />
            <Link to="/" style={{ textDecoration: "none" }}>
              <span className="navbar__title">Statis Cards</span>
            </Link>
          </div>
          <div className="navbar__links">
            <NavLink to="/">Home</NavLink>
            <NavLink to="/inventory">Inventory</NavLink>
            <NavLink to="/add">Add Item</NavLink>
            <NavLink to="/binder">Binder</NavLink>
            <NavDropdown
              label="Money"
              links={[
                { to: "/financials", label: "Financials" },
                { to: "/expenses", label: "Expenses" },
                { to: "/other", label: "Other Profits" },
              ]}
            />
            <NavDropdown
              label="Shows"
              links={[
                { to: "/shows", label: "Manage Shows" },
                { to: "/showpnl", label: "Show P&L" },
              ]}
            />
            <NavLink to="/insights">Insights</NavLink>
            <NavLink to="/exporttransactions">Export</NavLink>
            <NavLink to="/marketvaluecalculator">Calculator</NavLink>
          </div>
        </nav>

        <main className="main-content">
          <Routes>
            <Route path="/" element={<Home />} />
            <Route path="/financials" element={<Financials />} />
            <Route path="/inventory" element={<ItemsTable />} />
            <Route path="/add" element={<AddItem />} />
            <Route path="/expenses" element={<Expenses />} />
            <Route path="/other" element={<Other />} />
            <Route path="/binder" element={<Binder />} />
            <Route path="/shows" element={<Shows />} />
            <Route path="/showpnl" element={<ShowPnL />} />
            <Route path="/insights" element={<Insights />} />
            <Route
              path="/exporttransactions"
              element={<ExportTransactions />}
            />
            <Route
              path="/marketvaluecalculator"
              element={<MarketValueCalculator />}
            />
          </Routes>
        </main>
      </div>
    </Router>
  );
}

export default App;
