import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { API_BASE } from "../config";

const MIN_DATE = new Date("2020-01-01");
const isValidDate = (d) => {
  const dt = new Date(d);
  return d && !isNaN(dt.getTime()) && dt >= MIN_DATE;
};

const NavTile = ({ to, emoji, title, subtitle, color, stat, statLabel }) => (
  <Link to={to} style={{ textDecoration: "none" }}>
    <div
      style={{
        background: "var(--bg-card)",
        border: `1px solid var(--border)`,
        borderTop: `3px solid ${color}`,
        borderRadius: "var(--radius)",
        padding: "32px 28px",
        cursor: "pointer",
        transition: "transform 0.2s, box-shadow 0.2s, border-color 0.2s",
        display: "flex",
        flexDirection: "column",
        gap: 12,
        height: "100%",
      }}
      onMouseEnter={(e) => {
        e.currentTarget.style.transform = "translateY(-4px)";
        e.currentTarget.style.boxShadow = `0 8px 32px rgba(0,0,0,0.4)`;
        e.currentTarget.style.borderColor = color;
      }}
      onMouseLeave={(e) => {
        e.currentTarget.style.transform = "translateY(0)";
        e.currentTarget.style.boxShadow = "none";
        e.currentTarget.style.borderColor = "var(--border)";
        e.currentTarget.style.borderTopColor = color;
      }}
    >
      <div style={{ fontSize: 40 }}>{emoji}</div>
      <div>
        <div
          style={{
            fontFamily: "'Bebas Neue', sans-serif",
            fontSize: 28,
            letterSpacing: 2,
            color: "var(--text)",
            lineHeight: 1,
          }}
        >
          {title}
        </div>
        <div style={{ fontSize: 13, color: "var(--text-muted)", marginTop: 6 }}>
          {subtitle}
        </div>
      </div>
      {stat !== undefined && (
        <div
          style={{
            marginTop: "auto",
            paddingTop: 16,
            borderTop: "1px solid var(--border)",
          }}
        >
          <div
            style={{
              fontFamily: "'Bebas Neue', sans-serif",
              fontSize: 28,
              color,
              letterSpacing: 1,
            }}
          >
            {stat}
          </div>
          <div
            style={{
              fontSize: 11,
              color: "var(--text-muted)",
              textTransform: "uppercase",
              letterSpacing: "0.8px",
            }}
          >
            {statLabel}
          </div>
        </div>
      )}
    </div>
  </Link>
);

const Home = () => {
  const [stats, setStats] = useState(null);

  useEffect(() => {
    const fetchStats = async () => {
      try {
        const [ir, or, er] = await Promise.all([
          fetch(`${API_BASE}/api/items`),
          fetch(`${API_BASE}/api/other`),
          fetch(`${API_BASE}/api/expenses`),
        ]);
        const [items, other, expenses] = await Promise.all([
          ir.json(),
          or.json(),
          er.json(),
        ]);

        const unsold = items.filter((i) => i.soldPrice == null);
        const sold = items.filter((i) => i.soldPrice != null);

        const BINDER_SALE_PREFIX = "[Binder Sale]";
        const binderSales = other.filter((o) =>
          o.name?.startsWith(BINDER_SALE_PREFIX),
        );
        const binderRestocks = expenses.filter((e) => e.category === "Binder");
        const binderSalesTotal = binderSales.reduce(
          (s, o) => s + Number(o.amount),
          0,
        );
        const binderRestocksTotal = binderRestocks.reduce(
          (s, e) => s + Number(e.amount),
          0,
        );
        const binderNet = binderSalesTotal - binderRestocksTotal;

        const revenue = sold.reduce((s, i) => s + Number(i.soldPrice), 0);
        const cogs = sold.reduce((s, i) => s + Number(i.purchasePrice), 0);
        const nonBinderOther = other.filter(
          (o) => !o.name?.startsWith(BINDER_SALE_PREFIX),
        );
        const otherIncome = nonBinderOther.reduce(
          (s, o) => s + Number(o.amount),
          0,
        );
        const totalExpenses = expenses
          .filter((e) => e.category !== "Binder")
          .reduce((s, e) => s + Number(e.amount), 0);
        const netProfit =
          revenue - cogs + binderNet + otherIncome - totalExpenses;

        // Days since last sale
        const lastSold = sold
          .filter((i) => isValidDate(i.soldDate))
          .sort((a, b) => new Date(b.soldDate) - new Date(a.soldDate))[0];
        const daysSinceLastSale = lastSold
          ? Math.round((new Date() - new Date(lastSold.soldDate)) / 86400000)
          : null;

        // Stale cards
        const staleCount = unsold.filter((i) => {
          if (!isValidDate(i.purchaseDate)) return false;
          return (
            Math.round((new Date() - new Date(i.purchaseDate)) / 86400000) > 60
          );
        }).length;

        setStats({
          unsoldCount: unsold.length,
          inventoryValue: unsold.reduce(
            (s, i) => s + Number(i.purchasePrice),
            0,
          ),
          netProfit,
          binderNet,
          daysSinceLastSale,
          staleCount,
        });
      } catch {}
    };
    fetchStats();
  }, []);

  const fmt = (n) => {
    const abs = Math.abs(Number(n));
    const str = abs.toLocaleString("en-US", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    });
    return Number(n) < 0 ? `-$${str}` : `+$${str}`;
  };

  return (
    <div>
      {/* Header */}
      <div style={{ marginBottom: 40 }}>
        <h1
          style={{
            fontFamily: "'Bebas Neue', sans-serif",
            fontSize: 42,
            letterSpacing: 4,
            color: "var(--accent)",
            marginBottom: 6,
          }}
        >
          Statis Cards
        </h1>
        <p style={{ fontSize: 14, color: "var(--text-muted)" }}>
          Where do you want to go?
        </p>
      </div>

      {/* Quick stats strip */}
      {stats && (
        <div
          style={{
            display: "flex",
            gap: 24,
            marginBottom: 36,
            flexWrap: "wrap",
          }}
        >
          <div style={{ fontSize: 13, color: "var(--text-muted)" }}>
            <span style={{ color: "var(--text)", fontWeight: 600 }}>
              {stats.unsoldCount}
            </span>{" "}
            cards in inventory
          </div>
          <div style={{ fontSize: 13, color: "var(--text-muted)" }}>
            Net profit:{" "}
            <span
              style={{
                color: stats.netProfit >= 0 ? "var(--green)" : "var(--danger)",
                fontWeight: 600,
              }}
            >
              {fmt(stats.netProfit)}
            </span>
          </div>
          {stats.staleCount > 0 && (
            <div style={{ fontSize: 13, color: "var(--danger)" }}>
              ⚠ {stats.staleCount} stale card{stats.staleCount !== 1 ? "s" : ""}{" "}
              (60d+)
            </div>
          )}
          {stats.daysSinceLastSale !== null && (
            <div style={{ fontSize: 13, color: "var(--text-muted)" }}>
              Last sale:{" "}
              <span style={{ color: "var(--text)", fontWeight: 600 }}>
                {stats.daysSinceLastSale === 0
                  ? "today"
                  : `${stats.daysSinceLastSale}d ago`}
              </span>
            </div>
          )}
        </div>
      )}

      {/* Main nav tiles */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(240px, 1fr))",
          gap: 20,
          marginBottom: 20,
        }}
      >
        <NavTile
          to="/inventory"
          emoji="📦"
          title="Inventory"
          subtitle="Browse, search, and mark cards as sold"
          color="var(--blue)"
          stat={stats ? `${stats.unsoldCount} active` : "—"}
          statLabel="cards in stock"
        />
        <NavTile
          to="/add"
          emoji="➕"
          title="Add Card"
          subtitle="Log a new purchase to your inventory"
          color="var(--green)"
          stat={
            stats
              ? `$${stats.inventoryValue.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`
              : "—"
          }
          statLabel="inventory value at cost"
        />
        <NavTile
          to="/binder"
          emoji="📒"
          title="Binder"
          subtitle="Track binder restocks and sales"
          color="var(--accent)"
          stat={stats ? fmt(stats.binderNet) : "—"}
          statLabel="binder net profit"
        />
        <NavTile
          to="/marketvaluecalculator"
          emoji="🧮"
          title="Calculator"
          subtitle="Look up market values before buying"
          color="#a78bfa"
          stat={null}
        />
      </div>

      {/* Secondary links */}
      <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginTop: 8 }}>
        {[
          { to: "/financials", label: "Financials" },
          { to: "/shows", label: "Shows" },
          { to: "/showpnl", label: "Show P&L" },
          { to: "/insights", label: "Insights" },
          { to: "/expenses", label: "Expenses" },
          { to: "/other", label: "Other Profits" },
          { to: "/exporttransactions", label: "Export" },
        ].map((link) => (
          <Link key={link.to} to={link.to} style={{ textDecoration: "none" }}>
            <div className="btn btn-secondary btn-sm">{link.label}</div>
          </Link>
        ))}
      </div>
    </div>
  );
};

export default Home;
