import React, { useEffect, useState } from "react";
import { API_BASE } from "../config";

const today = () => new Date().toISOString().split("T")[0];

const CATEGORIES = ["Binder", "Admin", "Other"];

const CATEGORY_STYLES = {
  Binder: { bg: "rgba(74,179,216,0.15)", color: "var(--blue)" },
  Admin: { bg: "rgba(232,184,75,0.12)", color: "var(--accent)" },
  Other: { bg: "rgba(200,150,255,0.15)", color: "#d4a8ff" },
};

const CategoryBadge = ({ cat }) => {
  const style = CATEGORY_STYLES[cat] || {
    bg: "rgba(139,144,168,0.15)",
    color: "var(--text-muted)",
  };
  return (
    <span
      className="badge"
      style={{ background: style.bg, color: style.color }}
    >
      {cat || "Uncategorized"}
    </span>
  );
};

const Expenses = () => {
  const [expenses, setExpenses] = useState([]);
  const [formData, setFormData] = useState({
    name: "",
    category: "Admin",
    amount: "",
    date: today(),
    notes: "",
  });
  const [editingId, setEditingId] = useState(null);
  const [editData, setEditData] = useState({});
  const [categoryFilter, setCategoryFilter] = useState("All");
  const [toast, setToast] = useState({ msg: "", type: "success" });
  const [loading, setLoading] = useState(true);

  const showToast = (msg, type = "success") => {
    setToast({ msg, type });
    setTimeout(() => setToast({ msg: "", type: "success" }), 3000);
  };

  const fetchExpenses = async () => {
    const res = await fetch(`${API_BASE}/api/expenses`);
    const data = await res.json();
    setExpenses(data);
    setLoading(false);
  };

  useEffect(() => {
    fetchExpenses();
  }, []);

  const handleChange = (e) =>
    setFormData((p) => ({ ...p, [e.target.name]: e.target.value }));
  const handleEditChange = (e) =>
    setEditData((p) => ({ ...p, [e.target.name]: e.target.value }));

  const handleSubmit = async (e) => {
    e.preventDefault();
    const res = await fetch(`${API_BASE}/api/expenses`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(formData),
    });
    if (res.ok) {
      setFormData({
        name: "",
        category: "Admin",
        amount: "",
        date: today(),
        notes: "",
      });
      showToast("✓ Expense added!");
      fetchExpenses();
    } else {
      const d = await res.json();
      showToast("Error: " + d.error, "error");
    }
  };

  const handleEdit = (exp) => {
    setEditingId(exp._id);
    setEditData({
      name: exp.name,
      category: CATEGORIES.includes(exp.category) ? exp.category : "Other",
      amount: exp.amount,
      date: exp.date ? new Date(exp.date).toISOString().split("T")[0] : today(),
      notes: exp.notes || "",
    });
  };

  const handleEditSave = async (id) => {
    const res = await fetch(`${API_BASE}/api/expenses/${id}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(editData),
    });
    if (res.ok) {
      setEditingId(null);
      showToast("✓ Expense updated!");
      fetchExpenses();
    } else {
      const d = await res.json();
      showToast("Error: " + d.error, "error");
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm("Delete this expense?")) return;
    await fetch(`${API_BASE}/api/expenses/${id}`, { method: "DELETE" });
    showToast("Expense deleted.");
    fetchExpenses();
  };

  const filtered =
    categoryFilter === "All"
      ? expenses
      : categoryFilter === "Uncategorized"
        ? expenses.filter(
            (e) => !e.category || !CATEGORIES.includes(e.category),
          )
        : expenses.filter((e) => e.category === categoryFilter);

  const total = filtered.reduce((s, e) => s + Number(e.amount), 0);

  // Totals per category for summary
  const totals = CATEGORIES.reduce((acc, cat) => {
    acc[cat] = expenses
      .filter((e) => e.category === cat)
      .reduce((s, e) => s + Number(e.amount), 0);
    return acc;
  }, {});
  const uncategorizedTotal = expenses
    .filter((e) => !e.category || !CATEGORIES.includes(e.category))
    .reduce((s, e) => s + Number(e.amount), 0);
  const uncategorizedCount = expenses.filter(
    (e) => !e.category || !CATEGORIES.includes(e.category),
  ).length;

  return (
    <div>
      <h1 className="page-title">Expenses</h1>

      {/* Category summary cards */}
      <div className="stats-grid" style={{ marginBottom: 24 }}>
        {CATEGORIES.map((cat) => {
          const style = CATEGORY_STYLES[cat];
          return (
            <div
              key={cat}
              className="stat-card"
              style={{
                borderColor:
                  categoryFilter === cat ? style.color : "var(--border)",
                cursor: "pointer",
              }}
              onClick={() =>
                setCategoryFilter(categoryFilter === cat ? "All" : cat)
              }
            >
              <div className="stat-card__label">{cat}</div>
              <div className="stat-card__value" style={{ color: style.color }}>
                ${totals[cat].toFixed(2)}
              </div>
              <div
                style={{
                  fontSize: 12,
                  color: "var(--text-muted)",
                  marginTop: 4,
                }}
              >
                {expenses.filter((e) => e.category === cat).length} expense
                {expenses.filter((e) => e.category === cat).length !== 1
                  ? "s"
                  : ""}
              </div>
            </div>
          );
        })}
        {uncategorizedCount > 0 && (
          <div
            className="stat-card"
            style={{
              borderColor:
                categoryFilter === "Uncategorized"
                  ? "var(--text-muted)"
                  : "var(--border)",
              cursor: "pointer",
            }}
            onClick={() =>
              setCategoryFilter(
                categoryFilter === "Uncategorized" ? "All" : "Uncategorized",
              )
            }
          >
            <div className="stat-card__label">Uncategorized</div>
            <div
              className="stat-card__value"
              style={{ color: "var(--text-muted)" }}
            >
              ${uncategorizedTotal.toFixed(2)}
            </div>
            <div style={{ fontSize: 12, color: "var(--danger)", marginTop: 4 }}>
              {uncategorizedCount} need{uncategorizedCount === 1 ? "s" : ""} a
              category
            </div>
          </div>
        )}
      </div>

      {/* Add form */}
      <div className="card" style={{ maxWidth: 640, marginBottom: 28 }}>
        <p className="form-label" style={{ marginBottom: 16 }}>
          Add Expense
        </p>
        <form onSubmit={handleSubmit} className="form-grid" style={{ gap: 14 }}>
          <div className="form-grid form-grid-2">
            <div className="form-group">
              <label className="form-label">Name *</label>
              <input
                className="form-input"
                name="name"
                placeholder="e.g. Table fee"
                value={formData.name}
                onChange={handleChange}
                required
              />
            </div>
            <div className="form-group">
              <label className="form-label">Category *</label>
              <select
                className="form-select"
                name="category"
                value={formData.category}
                onChange={handleChange}
              >
                {CATEGORIES.map((c) => (
                  <option key={c} value={c}>
                    {c}
                  </option>
                ))}
              </select>
            </div>
          </div>
          <div className="form-grid form-grid-2">
            <div className="form-group">
              <label className="form-label">Amount *</label>
              <input
                className="form-input"
                type="number"
                name="amount"
                placeholder="0.00"
                step="0.01"
                min="0"
                value={formData.amount}
                onChange={handleChange}
                required
              />
            </div>
            <div className="form-group">
              <label className="form-label">Date</label>
              <input
                className="form-input"
                type="date"
                name="date"
                value={formData.date}
                onChange={handleChange}
              />
            </div>
          </div>
          <div className="form-group">
            <label className="form-label">Notes</label>
            <input
              className="form-input"
              name="notes"
              placeholder="Optional..."
              value={formData.notes}
              onChange={handleChange}
            />
          </div>
          <button type="submit" className="btn btn-primary">
            Add Expense
          </button>
        </form>
      </div>

      {/* Filter bar */}
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: 12,
          flexWrap: "wrap",
          gap: 10,
        }}
      >
        <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
          <button
            className={`btn btn-sm ${categoryFilter === "All" ? "btn-primary" : "btn-secondary"}`}
            onClick={() => setCategoryFilter("All")}
          >
            All
          </button>
          {CATEGORIES.map((cat) => (
            <button
              key={cat}
              className={`btn btn-sm ${categoryFilter === cat ? "btn-primary" : "btn-secondary"}`}
              onClick={() => setCategoryFilter(cat)}
              style={categoryFilter === cat ? {} : {}}
            >
              {cat}
            </button>
          ))}
          {uncategorizedCount > 0 && (
            <button
              className={`btn btn-sm ${categoryFilter === "Uncategorized" ? "btn-primary" : "btn-danger"}`}
              onClick={() => setCategoryFilter("Uncategorized")}
            >
              Uncategorized ({uncategorizedCount})
            </button>
          )}
        </div>
        <span style={{ fontWeight: 700, color: "var(--danger)", fontSize: 15 }}>
          {categoryFilter !== "All" ? `${categoryFilter}: ` : "Total: "}-$
          {total.toFixed(2)}
        </span>
      </div>

      {/* Table */}
      {loading ? (
        <div
          className="skeleton"
          style={{ height: 200, borderRadius: "var(--radius)" }}
        />
      ) : (
        <div className="table-wrapper">
          <table>
            <thead>
              <tr>
                <th>Name</th>
                <th>Category</th>
                <th>Amount</th>
                <th>Date</th>
                <th>Notes</th>
                <th></th>
              </tr>
            </thead>
            <tbody>
              {filtered.length === 0 ? (
                <tr>
                  <td
                    colSpan={6}
                    style={{
                      textAlign: "center",
                      color: "var(--text-muted)",
                      padding: 32,
                    }}
                  >
                    No expenses in this category.
                  </td>
                </tr>
              ) : (
                filtered.map((exp) => (
                  <tr key={exp._id}>
                    {editingId === exp._id ? (
                      <>
                        <td>
                          <input
                            className="form-input"
                            name="name"
                            value={editData.name}
                            onChange={handleEditChange}
                            style={{ minWidth: 120 }}
                          />
                        </td>
                        <td>
                          <select
                            className="form-select"
                            name="category"
                            value={editData.category}
                            onChange={handleEditChange}
                            style={{ minWidth: 110 }}
                          >
                            {CATEGORIES.map((c) => (
                              <option key={c} value={c}>
                                {c}
                              </option>
                            ))}
                          </select>
                        </td>
                        <td>
                          <input
                            className="form-input"
                            type="number"
                            name="amount"
                            value={editData.amount}
                            onChange={handleEditChange}
                            style={{ minWidth: 80 }}
                          />
                        </td>
                        <td>
                          <input
                            className="form-input"
                            type="date"
                            name="date"
                            value={editData.date}
                            onChange={handleEditChange}
                          />
                        </td>
                        <td>
                          <input
                            className="form-input"
                            name="notes"
                            value={editData.notes}
                            onChange={handleEditChange}
                            style={{ minWidth: 100 }}
                          />
                        </td>
                        <td>
                          <div style={{ display: "flex", gap: 6 }}>
                            <button
                              className="btn btn-success btn-sm"
                              onClick={() => handleEditSave(exp._id)}
                            >
                              Save
                            </button>
                            <button
                              className="btn btn-secondary btn-sm"
                              onClick={() => setEditingId(null)}
                            >
                              Cancel
                            </button>
                          </div>
                        </td>
                      </>
                    ) : (
                      <>
                        <td>{exp.name}</td>
                        <td>
                          <CategoryBadge cat={exp.category} />
                        </td>
                        <td style={{ color: "var(--danger)", fontWeight: 600 }}>
                          -${Number(exp.amount).toFixed(2)}
                        </td>
                        <td style={{ color: "var(--text-muted)" }}>
                          {new Date(exp.date).toLocaleDateString()}
                        </td>
                        <td
                          style={{
                            color: "var(--text-muted)",
                            fontStyle: "italic",
                          }}
                        >
                          {exp.notes || "—"}
                        </td>
                        <td>
                          <div style={{ display: "flex", gap: 6 }}>
                            <button
                              className="btn btn-secondary btn-sm"
                              onClick={() => handleEdit(exp)}
                            >
                              Edit
                            </button>
                            <button
                              className="btn btn-danger btn-sm"
                              onClick={() => handleDelete(exp._id)}
                            >
                              Delete
                            </button>
                          </div>
                        </td>
                      </>
                    )}
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      )}

      {toast.msg && (
        <div className={`toast toast-${toast.type}`}>{toast.msg}</div>
      )}
    </div>
  );
};

export default Expenses;
