import React, { useEffect, useState } from "react";
import { API_BASE } from "../config";

const today = () => new Date().toISOString().split("T")[0];
const fmt = (n) => `$${Math.abs(Number(n)).toFixed(2)}`;
const fmtSigned = (n) => `${Number(n) >= 0 ? "+" : "-"}${fmt(n)}`;
const BINDER_SALE_PREFIX = "[Binder Sale]";
const PAYMENT_METHODS = ["Cash", "Venmo - Ben", "Venmo - Owen", "Trade"];

const paymentBadge = (method) => {
  if (!method || method === "Cash")
    return (
      <span
        className="badge"
        style={{ background: "rgba(76,175,125,0.15)", color: "var(--green)" }}
      >
        Cash
      </span>
    );
  if (method === "Venmo - Ben")
    return (
      <span
        className="badge"
        style={{ background: "rgba(74,179,216,0.15)", color: "var(--blue)" }}
      >
        Venmo - Ben
      </span>
    );
  if (method === "Venmo - Owen")
    return (
      <span
        className="badge"
        style={{ background: "rgba(232,184,75,0.12)", color: "var(--accent)" }}
      >
        Venmo - Owen
      </span>
    );
  if (method === "Trade")
    return (
      <span
        className="badge"
        style={{ background: "rgba(167,139,250,0.15)", color: "#a78bfa" }}
      >
        Trade
      </span>
    );
  return <span className="badge">{method}</span>;
};

const encodeSaleName = (notes, payment, cardCount) => {
  const countPart = cardCount ? `[${cardCount}]` : "";
  return `${BINDER_SALE_PREFIX}[${payment || "Cash"}]${countPart} ${notes || ""}`.trim();
};

const decodeSale = (entry) => {
  const match = entry.name?.match(
    /^\[Binder Sale\]\[([^\]]+)\](?:\[(\d+)\])?\s*(.*)/,
  );
  if (match)
    return {
      payment: match[1],
      cardCount: match[2] ? parseInt(match[2]) : null,
      notes: match[3] || entry.notes || "",
    };
  return { payment: "Cash", cardCount: null, notes: entry.notes || "" };
};

const Binder = () => {
  const [restocks, setRestocks] = useState([]);
  const [sales, setSales] = useState([]);
  const [untagged, setUntagged] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showReclassify, setShowReclassify] = useState(false);
  const [toast, setToast] = useState({ msg: "", type: "success" });

  // Card count from backend
  const [binderCount, setBinderCount] = useState(null);
  const [editingCount, setEditingCount] = useState(false);
  const [countInput, setCountInput] = useState("");
  const [savingCount, setSavingCount] = useState(false);

  const [restockForm, setRestockForm] = useState({
    name: "",
    cardCount: "",
    amount: "",
    date: today(),
    notes: "",
  });
  const [saleForm, setSaleForm] = useState({
    cardCount: "",
    amount: "",
    date: today(),
    notes: "",
    payment: "Cash",
  });

  const [editingRestock, setEditingRestock] = useState(null);
  const [editRestockData, setEditRestockData] = useState({});
  const [editingSale, setEditingSale] = useState(null);
  const [editSaleData, setEditSaleData] = useState({});

  const showToast = (msg, type = "success") => {
    setToast({ msg, type });
    setTimeout(() => setToast({ msg: "", type: "success" }), 3000);
  };

  const fetchData = async () => {
    const [expRes, otherRes, configRes] = await Promise.all([
      fetch(`${API_BASE}/api/expenses`),
      fetch(`${API_BASE}/api/other`),
      fetch(`${API_BASE}/api/binder-config`),
    ]);
    const [expenses, other, config] = await Promise.all([
      expRes.json(),
      otherRes.json(),
      configRes.json(),
    ]);
    setRestocks(expenses.filter((e) => e.category === "Binder"));
    setSales(other.filter((o) => o.name?.startsWith(BINDER_SALE_PREFIX)));
    setUntagged(other.filter((o) => !o.name?.startsWith(BINDER_SALE_PREFIX)));
    setBinderCount(config.cardCount);
    setLoading(false);
  };

  useEffect(() => {
    fetchData();
  }, []);

  // ── Save binder count to backend ──
  const handleSaveCount = async () => {
    const val = parseInt(countInput);
    if (isNaN(val) || val < 0) {
      showToast("Please enter a valid number", "error");
      return;
    }
    setSavingCount(true);
    try {
      const res = await fetch(`${API_BASE}/api/binder-config`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ cardCount: val }),
      });
      if (res.ok) {
        const data = await res.json();
        setBinderCount(data.cardCount);
        setEditingCount(false);
        showToast("✓ Binder count updated!");
      } else {
        showToast("Error saving count", "error");
      }
    } catch {
      showToast("Error saving count", "error");
    } finally {
      setSavingCount(false);
    }
  };

  // ── Reclassify ──
  const reclassifyAsBinder = async (entry) => {
    const res = await fetch(`${API_BASE}/api/other/${entry._id}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        name: encodeSaleName(entry.name, "Cash", null),
        amount: entry.amount,
        date: entry.date,
        notes: entry.notes || "",
      }),
    });
    if (res.ok) {
      showToast(`✓ "${entry.name}" marked as Binder Sale`);
      fetchData();
    } else showToast("Error reclassifying entry", "error");
  };

  // ── Add restock ──
  const handleRestockSubmit = async (e) => {
    e.preventDefault();
    const res = await fetch(`${API_BASE}/api/expenses`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        name: restockForm.name,
        category: "Binder",
        amount: restockForm.amount,
        date: restockForm.date,
        notes: restockForm.notes,
      }),
    });
    if (res.ok) {
      setRestockForm({
        name: "",
        cardCount: "",
        amount: "",
        date: today(),
        notes: "",
      });
      showToast("✓ Restock added!");
      fetchData();
    } else {
      const d = await res.json();
      showToast("Error: " + d.error, "error");
    }
  };

  // ── Add sale ──
  const handleSaleSubmit = async (e) => {
    e.preventDefault();
    const res = await fetch(`${API_BASE}/api/other`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        name: encodeSaleName(
          saleForm.notes,
          saleForm.payment,
          saleForm.cardCount,
        ),
        amount: saleForm.amount,
        date: saleForm.date,
        notes: saleForm.notes,
      }),
    });
    if (res.ok) {
      setSaleForm({
        cardCount: "",
        amount: "",
        date: today(),
        notes: "",
        payment: "Cash",
      });
      showToast("✓ Sale recorded!");
      fetchData();
    } else {
      const d = await res.json();
      showToast("Error: " + d.error, "error");
    }
  };

  // ── Edit restock ──
  const handleEditRestockSave = async (id) => {
    const res = await fetch(`${API_BASE}/api/expenses/${id}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        name: editRestockData.name,
        category: "Binder",
        amount: editRestockData.amount,
        date: editRestockData.date,
        notes: editRestockData.notes,
      }),
    });
    if (res.ok) {
      setEditingRestock(null);
      showToast("✓ Updated!");
      fetchData();
    } else {
      const d = await res.json();
      showToast("Error: " + d.error, "error");
    }
  };

  // ── Edit sale ──
  const handleEditSaleSave = async (id) => {
    const res = await fetch(`${API_BASE}/api/other/${id}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        name: encodeSaleName(
          editSaleData.notes,
          editSaleData.payment,
          editSaleData.cardCount,
        ),
        amount: editSaleData.amount,
        date: editSaleData.date,
        notes: editSaleData.notes,
      }),
    });
    if (res.ok) {
      setEditingSale(null);
      showToast("✓ Updated!");
      fetchData();
    } else {
      const d = await res.json();
      showToast("Error: " + d.error, "error");
    }
  };

  const handleDeleteRestock = async (id) => {
    if (!window.confirm("Delete this restock entry?")) return;
    await fetch(`${API_BASE}/api/expenses/${id}`, { method: "DELETE" });
    showToast("Deleted.");
    fetchData();
  };

  const handleDeleteSale = async (id) => {
    if (!window.confirm("Delete this sale entry?")) return;
    await fetch(`${API_BASE}/api/other/${id}`, { method: "DELETE" });
    showToast("Deleted.");
    fetchData();
  };

  const totalRestocks = restocks.reduce((s, r) => s + Number(r.amount), 0);
  const totalSales = sales.reduce((s, r) => s + Number(r.amount), 0);
  const binderProfit = totalSales - totalRestocks;
  const roi =
    totalRestocks > 0 ? ((totalSales / totalRestocks) * 100).toFixed(0) : null;

  const digitalBen = sales
    .filter((s) => decodeSale(s).payment === "Venmo - Ben")
    .reduce((sum, s) => sum + Number(s.amount), 0);
  const digitalOwen = sales
    .filter((s) => decodeSale(s).payment === "Venmo - Owen")
    .reduce((sum, s) => sum + Number(s.amount), 0);

  const totalCardsSold = sales.reduce((s, sale) => {
    const { cardCount } = decodeSale(sale);
    return s + (cardCount || 0);
  }, 0);

  const timeline = [
    ...restocks.map((r) => ({
      ...r,
      _type: "restock",
      _date: new Date(r.date),
    })),
    ...sales.map((s) => ({
      ...s,
      _type: "sale",
      _date: new Date(s.date),
      ...decodeSale(s),
    })),
  ].sort((a, b) => b._date - a._date);

  return (
    <div>
      <h1 className="page-title">Binder</h1>

      {/* Reclassify banner */}
      {untagged.length > 0 && (
        <div
          style={{
            background: "rgba(232,184,75,0.08)",
            border: "1px solid rgba(232,184,75,0.3)",
            borderRadius: "var(--radius)",
            padding: "14px 18px",
            marginBottom: 24,
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            flexWrap: "wrap",
            gap: 10,
          }}
        >
          <div>
            <span style={{ fontWeight: 700, color: "var(--accent)" }}>
              ⚠ {untagged.length} unclassified Other entr
              {untagged.length !== 1 ? "ies" : "y"}
            </span>
            <span
              style={{
                color: "var(--text-muted)",
                fontSize: 13,
                marginLeft: 8,
              }}
            >
              — some may be binder sales.
            </span>
          </div>
          <button
            className={`btn btn-sm ${showReclassify ? "btn-primary" : "btn-secondary"}`}
            onClick={() => setShowReclassify((p) => !p)}
          >
            {showReclassify ? "Hide" : "Review & Reclassify"}
          </button>
        </div>
      )}

      {showReclassify && untagged.length > 0 && (
        <div className="card" style={{ marginBottom: 28 }}>
          <div
            style={{
              fontFamily: "'Bebas Neue', sans-serif",
              fontSize: 18,
              letterSpacing: 1,
              marginBottom: 4,
            }}
          >
            Unclassified Other Entries
          </div>
          <p
            style={{
              fontSize: 13,
              color: "var(--text-muted)",
              marginBottom: 16,
            }}
          >
            Click{" "}
            <strong style={{ color: "var(--blue)" }}>→ Binder Sale</strong> to
            move it here, or leave it in Other Profits.
          </p>
          <div className="table-wrapper">
            <table>
              <thead>
                <tr>
                  <th>Name</th>
                  <th>Amount</th>
                  <th>Date</th>
                  <th>Notes</th>
                  <th></th>
                </tr>
              </thead>
              <tbody>
                {untagged.map((entry) => (
                  <tr key={entry._id}>
                    <td style={{ fontWeight: 500 }}>{entry.name}</td>
                    <td style={{ color: "var(--green)", fontWeight: 600 }}>
                      +{fmt(entry.amount)}
                    </td>
                    <td style={{ color: "var(--text-muted)" }}>
                      {new Date(entry.date).toLocaleDateString()}
                    </td>
                    <td
                      style={{
                        color: "var(--text-muted)",
                        fontStyle: "italic",
                      }}
                    >
                      {entry.notes || "—"}
                    </td>
                    <td>
                      <button
                        className="btn btn-sm"
                        style={{
                          background: "rgba(74,179,216,0.15)",
                          color: "var(--blue)",
                          border: "1px solid rgba(74,179,216,0.3)",
                        }}
                        onClick={() => reclassifyAsBinder(entry)}
                      >
                        → Binder Sale
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Summary cards */}
      <div className="stats-grid" style={{ marginBottom: 28 }}>
        {/* Binder count hero card */}
        <div
          className="stat-card stat-card--accent"
          style={{ gridColumn: "span 2" }}
        >
          <div className="stat-card__label">Cards in Binder</div>
          {loading ? (
            <div
              className="skeleton"
              style={{ height: 52, width: "60%", marginBottom: 8 }}
            />
          ) : editingCount ? (
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: 10,
                marginTop: 4,
              }}
            >
              <input
                type="number"
                className="form-input"
                value={countInput}
                onChange={(e) => setCountInput(e.target.value)}
                style={{
                  width: 120,
                  fontSize: 28,
                  fontFamily: "'Bebas Neue', sans-serif",
                  padding: "4px 10px",
                }}
                autoFocus
                min="0"
                onKeyDown={(e) => {
                  if (e.key === "Enter") handleSaveCount();
                  if (e.key === "Escape") setEditingCount(false);
                }}
              />
              <button
                className="btn btn-success btn-sm"
                onClick={handleSaveCount}
                disabled={savingCount}
              >
                {savingCount ? "Saving..." : "Save"}
              </button>
              <button
                className="btn btn-secondary btn-sm"
                onClick={() => setEditingCount(false)}
              >
                Cancel
              </button>
            </div>
          ) : (
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: 16,
                marginTop: 4,
              }}
            >
              <div
                style={{
                  fontFamily: "'Bebas Neue', sans-serif",
                  fontSize: 52,
                  color: "var(--accent)",
                  lineHeight: 1,
                }}
              >
                {binderCount ?? "—"}
              </div>
              <button
                className="btn btn-secondary btn-sm"
                onClick={() => {
                  setCountInput(String(binderCount ?? 0));
                  setEditingCount(true);
                }}
                style={{ marginTop: 4 }}
              >
                ✏ Edit
              </button>
            </div>
          )}
          <div
            style={{ fontSize: 12, color: "var(--text-muted)", marginTop: 6 }}
          >
            {totalCardsSold > 0
              ? `${totalCardsSold} cards sold via binder this period`
              : "Set the current count and update it after each session"}
          </div>
        </div>

        {/* P&L summary */}
        <div className="stat-card stat-card--accent">
          <div className="stat-card__label">Binder Net Profit</div>
          <div
            className="stat-card__value"
            style={{
              fontSize: 32,
              color: binderProfit >= 0 ? "var(--green)" : "var(--danger)",
            }}
          >
            {fmtSigned(binderProfit)}
          </div>
          {roi !== null && (
            <div
              style={{ fontSize: 12, color: "var(--text-muted)", marginTop: 4 }}
            >
              {fmt(totalSales)} revenue · {fmt(totalRestocks)} spent ·{" "}
              <span
                style={{
                  color: binderProfit >= 0 ? "var(--green)" : "var(--danger)",
                  fontWeight: 700,
                }}
              >
                {roi}% ROI
              </span>
            </div>
          )}
        </div>

        <div className="stat-card">
          <div className="stat-card__label">Total Restocked</div>
          <div className="stat-card__value" style={{ color: "var(--danger)" }}>
            -{fmt(totalRestocks)}
          </div>
          <div
            style={{ fontSize: 12, color: "var(--text-muted)", marginTop: 4 }}
          >
            {restocks.length} restock{restocks.length !== 1 ? "s" : ""}
          </div>
        </div>

        <div className="stat-card">
          <div className="stat-card__label">Total Sales</div>
          <div className="stat-card__value" style={{ color: "var(--green)" }}>
            +{fmt(totalSales)}
          </div>
          <div
            style={{ fontSize: 12, color: "var(--text-muted)", marginTop: 4 }}
          >
            {sales.length} sale{sales.length !== 1 ? "s" : ""} ·{" "}
            {totalCardsSold} cards
          </div>
        </div>

        {digitalBen > 0 && (
          <div className="stat-card">
            <div className="stat-card__label">Venmo - Ben</div>
            <div className="stat-card__value" style={{ color: "var(--blue)" }}>
              {fmt(digitalBen)}
            </div>
            <div
              style={{ fontSize: 12, color: "var(--text-muted)", marginTop: 4 }}
            >
              needs converting
            </div>
          </div>
        )}
        {digitalOwen > 0 && (
          <div className="stat-card">
            <div className="stat-card__label">Venmo - Owen</div>
            <div
              className="stat-card__value"
              style={{ color: "var(--accent)" }}
            >
              {fmt(digitalOwen)}
            </div>
            <div
              style={{ fontSize: 12, color: "var(--text-muted)", marginTop: 4 }}
            >
              needs converting
            </div>
          </div>
        )}
      </div>

      {/* Forms */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "1fr 1fr",
          gap: 20,
          marginBottom: 32,
        }}
      >
        {/* Restock */}
        <div className="card" style={{ borderTop: "3px solid var(--danger)" }}>
          <p
            className="form-label"
            style={{ marginBottom: 16, color: "var(--danger)" }}
          >
            Record Restock (Buying Cards)
          </p>
          <form
            onSubmit={handleRestockSubmit}
            className="form-grid"
            style={{ gap: 12 }}
          >
            <div className="form-group">
              <label className="form-label">Description *</label>
              <input
                className="form-input"
                placeholder="e.g. Trainer commons pack"
                value={restockForm.name}
                onChange={(e) =>
                  setRestockForm((p) => ({ ...p, name: e.target.value }))
                }
                required
              />
            </div>
            <div className="form-grid form-grid-2">
              <div className="form-group">
                <label className="form-label">Cards Added</label>
                <input
                  className="form-input"
                  type="number"
                  placeholder="e.g. 20"
                  min="0"
                  step="1"
                  value={restockForm.cardCount}
                  onChange={(e) =>
                    setRestockForm((p) => ({ ...p, cardCount: e.target.value }))
                  }
                />
              </div>
              <div className="form-group">
                <label className="form-label">Amount Spent *</label>
                <input
                  className="form-input"
                  type="number"
                  placeholder="0.00"
                  step="0.01"
                  min="0"
                  value={restockForm.amount}
                  onChange={(e) =>
                    setRestockForm((p) => ({ ...p, amount: e.target.value }))
                  }
                  required
                />
              </div>
            </div>
            <div className="form-group">
              <label className="form-label">Date</label>
              <input
                className="form-input"
                type="date"
                value={restockForm.date}
                onChange={(e) =>
                  setRestockForm((p) => ({ ...p, date: e.target.value }))
                }
              />
            </div>
            <div className="form-group">
              <label className="form-label">Notes</label>
              <input
                className="form-input"
                placeholder="Optional..."
                value={restockForm.notes}
                onChange={(e) =>
                  setRestockForm((p) => ({ ...p, notes: e.target.value }))
                }
              />
            </div>
            <button
              type="submit"
              className="btn btn-danger"
              style={{ width: "100%" }}
            >
              + Add Restock
            </button>
          </form>
        </div>

        {/* Sale */}
        <div className="card" style={{ borderTop: "3px solid var(--green)" }}>
          <p
            className="form-label"
            style={{ marginBottom: 16, color: "var(--green)" }}
          >
            Record Sale (Selling Cards)
          </p>
          <form
            onSubmit={handleSaleSubmit}
            className="form-grid"
            style={{ gap: 12 }}
          >
            <div className="form-grid form-grid-2">
              <div className="form-group">
                <label className="form-label">Cards Sold</label>
                <input
                  className="form-input"
                  type="number"
                  placeholder="e.g. 5"
                  min="0"
                  step="1"
                  value={saleForm.cardCount}
                  onChange={(e) =>
                    setSaleForm((p) => ({ ...p, cardCount: e.target.value }))
                  }
                />
              </div>
              <div className="form-group">
                <label className="form-label">Total Received *</label>
                <input
                  className="form-input"
                  type="number"
                  placeholder="0.00"
                  step="0.01"
                  min="0"
                  value={saleForm.amount}
                  onChange={(e) =>
                    setSaleForm((p) => ({ ...p, amount: e.target.value }))
                  }
                  required
                />
              </div>
            </div>
            <div className="form-group">
              <label className="form-label">Payment Method</label>
              <select
                className="form-select"
                value={saleForm.payment}
                onChange={(e) =>
                  setSaleForm((p) => ({ ...p, payment: e.target.value }))
                }
              >
                {PAYMENT_METHODS.map((m) => (
                  <option key={m} value={m}>
                    {m}
                  </option>
                ))}
              </select>
            </div>
            <div className="form-group">
              <label className="form-label">Date</label>
              <input
                className="form-input"
                type="date"
                value={saleForm.date}
                onChange={(e) =>
                  setSaleForm((p) => ({ ...p, date: e.target.value }))
                }
              />
            </div>
            <div className="form-group">
              <label className="form-label">Notes</label>
              <input
                className="form-input"
                placeholder="e.g. Sold 5 trainers at show"
                value={saleForm.notes}
                onChange={(e) =>
                  setSaleForm((p) => ({ ...p, notes: e.target.value }))
                }
              />
            </div>
            <button
              type="submit"
              className="btn btn-success"
              style={{ width: "100%" }}
            >
              + Record Sale
            </button>
          </form>
        </div>
      </div>

      {/* Activity table */}
      {loading ? (
        <div
          className="skeleton"
          style={{ height: 200, borderRadius: "var(--radius)" }}
        />
      ) : timeline.length === 0 ? (
        <div
          className="card"
          style={{
            textAlign: "center",
            padding: 48,
            color: "var(--text-muted)",
          }}
        >
          No binder activity yet.
        </div>
      ) : (
        <>
          <h3
            style={{
              fontFamily: "'Bebas Neue', sans-serif",
              fontSize: 18,
              letterSpacing: 1,
              marginBottom: 12,
              color: "var(--text-muted)",
            }}
          >
            Activity
          </h3>
          <div className="table-wrapper">
            <table>
              <thead>
                <tr>
                  <th>Type</th>
                  <th>Cards</th>
                  <th>Amount</th>
                  <th>Payment</th>
                  <th>Date</th>
                  <th>Notes</th>
                  <th></th>
                </tr>
              </thead>
              <tbody>
                {timeline.map((entry) => (
                  <tr key={entry._id}>
                    {entry._type === "restock" ? (
                      editingRestock === entry._id ? (
                        <>
                          <td>
                            <span
                              className="badge"
                              style={{
                                background: "rgba(224,92,92,0.15)",
                                color: "var(--danger)",
                              }}
                            >
                              Restock
                            </span>
                          </td>
                          <td>
                            <span
                              style={{
                                color: "var(--text-muted)",
                                fontSize: 12,
                              }}
                            >
                              —
                            </span>
                          </td>
                          <td>
                            <input
                              className="form-input"
                              type="number"
                              value={editRestockData.amount}
                              onChange={(e) =>
                                setEditRestockData((p) => ({
                                  ...p,
                                  amount: e.target.value,
                                }))
                              }
                              style={{ minWidth: 80 }}
                            />
                          </td>
                          <td>
                            <span
                              style={{
                                color: "var(--text-muted)",
                                fontSize: 12,
                              }}
                            >
                              —
                            </span>
                          </td>
                          <td>
                            <input
                              className="form-input"
                              type="date"
                              value={editRestockData.date}
                              onChange={(e) =>
                                setEditRestockData((p) => ({
                                  ...p,
                                  date: e.target.value,
                                }))
                              }
                            />
                          </td>
                          <td>
                            <input
                              className="form-input"
                              value={editRestockData.name}
                              onChange={(e) =>
                                setEditRestockData((p) => ({
                                  ...p,
                                  name: e.target.value,
                                }))
                              }
                              style={{ minWidth: 100 }}
                            />
                          </td>
                          <td>
                            <div style={{ display: "flex", gap: 6 }}>
                              <button
                                className="btn btn-success btn-sm"
                                onClick={() => handleEditRestockSave(entry._id)}
                              >
                                Save
                              </button>
                              <button
                                className="btn btn-secondary btn-sm"
                                onClick={() => setEditingRestock(null)}
                              >
                                Cancel
                              </button>
                            </div>
                          </td>
                        </>
                      ) : (
                        <>
                          <td>
                            <span
                              className="badge"
                              style={{
                                background: "rgba(224,92,92,0.15)",
                                color: "var(--danger)",
                              }}
                            >
                              Restock
                            </span>
                          </td>
                          <td style={{ color: "var(--text-muted)" }}>—</td>
                          <td
                            style={{ color: "var(--danger)", fontWeight: 600 }}
                          >
                            -{fmt(entry.amount)}
                          </td>
                          <td>
                            <span
                              style={{
                                color: "var(--text-muted)",
                                fontSize: 12,
                              }}
                            >
                              —
                            </span>
                          </td>
                          <td style={{ color: "var(--text-muted)" }}>
                            {new Date(entry.date).toLocaleDateString()}
                          </td>
                          <td
                            style={{
                              color: "var(--text-muted)",
                              fontStyle: "italic",
                            }}
                          >
                            {entry.name || "—"}
                          </td>
                          <td>
                            <div style={{ display: "flex", gap: 6 }}>
                              <button
                                className="btn btn-secondary btn-sm"
                                onClick={() => {
                                  setEditingRestock(entry._id);
                                  setEditRestockData({
                                    name: entry.name,
                                    amount: entry.amount,
                                    date: new Date(entry.date)
                                      .toISOString()
                                      .split("T")[0],
                                    notes: entry.notes || "",
                                  });
                                }}
                              >
                                Edit
                              </button>
                              <button
                                className="btn btn-danger btn-sm"
                                onClick={() => handleDeleteRestock(entry._id)}
                              >
                                Delete
                              </button>
                            </div>
                          </td>
                        </>
                      )
                    ) : editingSale === entry._id ? (
                      <>
                        <td>
                          <span
                            className="badge"
                            style={{
                              background: "rgba(76,175,125,0.15)",
                              color: "var(--green)",
                            }}
                          >
                            Sale
                          </span>
                        </td>
                        <td>
                          <input
                            className="form-input"
                            type="number"
                            value={editSaleData.cardCount}
                            onChange={(e) =>
                              setEditSaleData((p) => ({
                                ...p,
                                cardCount: e.target.value,
                              }))
                            }
                            style={{ minWidth: 60 }}
                            placeholder="—"
                          />
                        </td>
                        <td>
                          <input
                            className="form-input"
                            type="number"
                            value={editSaleData.amount}
                            onChange={(e) =>
                              setEditSaleData((p) => ({
                                ...p,
                                amount: e.target.value,
                              }))
                            }
                            style={{ minWidth: 80 }}
                          />
                        </td>
                        <td>
                          <select
                            className="form-select"
                            value={editSaleData.payment}
                            onChange={(e) =>
                              setEditSaleData((p) => ({
                                ...p,
                                payment: e.target.value,
                              }))
                            }
                            style={{ minWidth: 120 }}
                          >
                            {PAYMENT_METHODS.map((m) => (
                              <option key={m} value={m}>
                                {m}
                              </option>
                            ))}
                          </select>
                        </td>
                        <td>
                          <input
                            className="form-input"
                            type="date"
                            value={editSaleData.date}
                            onChange={(e) =>
                              setEditSaleData((p) => ({
                                ...p,
                                date: e.target.value,
                              }))
                            }
                          />
                        </td>
                        <td>
                          <input
                            className="form-input"
                            value={editSaleData.notes}
                            onChange={(e) =>
                              setEditSaleData((p) => ({
                                ...p,
                                notes: e.target.value,
                              }))
                            }
                            style={{ minWidth: 100 }}
                          />
                        </td>
                        <td>
                          <div style={{ display: "flex", gap: 6 }}>
                            <button
                              className="btn btn-success btn-sm"
                              onClick={() => handleEditSaleSave(entry._id)}
                            >
                              Save
                            </button>
                            <button
                              className="btn btn-secondary btn-sm"
                              onClick={() => setEditingSale(null)}
                            >
                              Cancel
                            </button>
                          </div>
                        </td>
                      </>
                    ) : (
                      <>
                        <td>
                          <span
                            className="badge"
                            style={{
                              background: "rgba(76,175,125,0.15)",
                              color: "var(--green)",
                            }}
                          >
                            Sale
                          </span>
                        </td>
                        <td style={{ color: "var(--text-muted)" }}>
                          {entry.cardCount != null
                            ? `-${entry.cardCount}`
                            : "—"}
                        </td>
                        <td style={{ color: "var(--green)", fontWeight: 600 }}>
                          +{fmt(entry.amount)}
                        </td>
                        <td>{paymentBadge(entry.payment)}</td>
                        <td style={{ color: "var(--text-muted)" }}>
                          {new Date(entry.date).toLocaleDateString()}
                        </td>
                        <td
                          style={{
                            color: "var(--text-muted)",
                            fontStyle: "italic",
                          }}
                        >
                          {entry.notes || "—"}
                        </td>
                        <td>
                          <div style={{ display: "flex", gap: 6 }}>
                            <button
                              className="btn btn-secondary btn-sm"
                              onClick={() => {
                                setEditingSale(entry._id);
                                setEditSaleData({
                                  cardCount: entry.cardCount || "",
                                  amount: entry.amount,
                                  date: new Date(entry.date)
                                    .toISOString()
                                    .split("T")[0],
                                  notes: entry.notes || "",
                                  payment: entry.payment || "Cash",
                                });
                              }}
                            >
                              Edit
                            </button>
                            <button
                              className="btn btn-danger btn-sm"
                              onClick={() => handleDeleteSale(entry._id)}
                            >
                              Delete
                            </button>
                          </div>
                        </td>
                      </>
                    )}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </>
      )}

      {toast.msg && (
        <div className={`toast toast-${toast.type}`}>{toast.msg}</div>
      )}
    </div>
  );
};

export default Binder;
